\newcommand{\atx}{A_t\of{x}}

\begin{algorithm}\label{weakpea}
    \caption{Collaborative prediction with expert advice [simplified algorithm]}
    \Let{$A_1$}{$\init{\experts, \epsilon = \sqrt{\logo{M} / T}}$}
    \For{$x \in \experts$, $u \in \users$}{
        \Let{$B^{xu}$}{$\init{\b{0, 1}, \epsilon = \sqrt{N/T}}$}
    }
    \For{$t = 1, 2, \ldots$}{
        Observe $u_t \in \users$\;
        \For{$x \in \experts$}{
            \Let{$z_t^x$}{$B^{xu_t}\of{1}$}
            \Let{$w_t^x$}{$z_t^x \atx$}
        }
        \Let{$W_t$}{$\sum_x w_t^x$}
        Play $p_t\of{x} = w_t^x / W_t \in \Delta\of{\experts}$\;
        Observe $\ell_t : \experts \rightarrow [-1, 1]$\;
        \For{$x \in \experts$}{
            \Let{$\ell_t^A\of{x}$}{$z_t^x \ell_t\of{x} + (1 - z_t^x) \ell_t\of{p_t}$}
            \Let{$\ell_t^{B^{xu_t}}\of{1}$}{$\ell_t\of{x}$}
            \Let{$\ell_t^{B^{xu_t}}\of{0}$}{$\ell_t\of{p_t}$}
            \Let{$B^{xu_t}$}{$\update{B^{xu_t}}{\ell_t^{B^{xu_t}}}$}
        }
        \Let{$A_{t+1}$}{$\update{A_t}{\ell_t^A}$}
    }
\end{algorithm}

Our first lemma
shows that the excess loss of expert $x$ in the rounds
where it opts to make a prediction
is at most the excess loss of expert $x$ in rounds involving a user $u_t \in H$.
\begin{lemma}\label{reverselemma}
For every $x \in \experts$:
\[\sum_{t \leq T} z_t^x \ps{\ell_t\of{x} - \ell_t\of{p_t}} \leq \sum_{t \leq T : u_t \in H} \ps{\ell_t\of{x} - \ell_t\of{p_t}} + \O{\sqrt{T N}}\]
\end{lemma}
\begin{proof}

We apply Lemma~\ref{mwm} to each $\mwm$ instance $B^{xu}$,
and sum the resulting inequalities.
Write $h_u = 1$ if $u \in H$, and $0$ otherwise, and let $T_u = \abs{\b{t : u_t = u}}$.
\begin{align*}
\sum_{t \leq T} z_t^x \ps{\ell_t\of{x} - \ell_t\of{p_t}}
&= \sum_{u \in \users} \sum_{t \leq T : u_t = u} z_t^x \ps{\ell_t\of{x} - \ell_t\of{p_t}} \\
&\leq \sum_{u \in \users}  \ps{
\O{\sqrt{T/N} + T_u \sqrt{N/T}} + 
\sum_{t \leq T : u_t = u} h_u \ps{\ell_t\of{x} - \ell_t\of{p_t}}
} \\
&= \O{\sqrt{NT}} + \sum_{t \leq T : u_t \in H} \ps{\ell_t\of{x} - \ell_t\of{p_t}}
\end{align*}
as desired.
\end{proof}


\newcommand{\ra}{ \O{\sqrt{T \logo{M}}}}

Our second lemma shows that excess loss of an expert, in the rounds where it makes a prediction,
cannot be too large.
\begin{lemma}\label{specialistlemma}
For any $x \in \experts$,
\[\sum_{t \leq T} z_t^x \ps{\ell_t\of{p_t} - \ell_t\of{x}}  \leq \ra \]
\end{lemma}
\begin{proof}
First, we observe that $\ell^A_t\of{A_t} = \ell_t\of{p_t}$:
\begin{align*}
\ell^A_t\of{A_t} 
&= \sum_x \atx \ps{z_t^x \ell_t\of{x} + (1 - z_t^x) \ell_t\of{p_t}} \\
&= \sum_x\atx z_t^x \ell_t\of{x} + \ell_t\of{p_t} \sum_x \atx - \ell_t\of{p_t} \sum_x \atx z_t^x \\
&= \sum_x w_t^x \ell_t\of{x}  + \ell_t\of{p_t} - \ell_t\of{p_t} \sum_x w_t^x \\
&= W_t \ell_t\of{p_t} + \ell_t\of{p_t} - W_t \ell_t\of{p_t} \\
&= \ell_t\of{p_t}.
\end{align*}
So we can apply the regret bound for $A$, and obtain:
\begin{align*}
\sum_{t \leq T} \ell_t\of{p_t}
&= \sum_{t \leq T} \ell^A_t\of{A_t} \\
&\leq \sum_{t \leq T} \ell^A_t\of{x} + \ra \\
&= \sum_{t \leq T} \ps{z_t^x \ell_t\of{x} + (1 - z_t^x) \ell_t\of{p_t}} + \ra \\
&= \sum_{t \leq T} \ell_t\of{p_t} + \sum_{t \leq T} z_t^x \ps{\ell_t\of{x} - \ell_t\of{p_t}} + \ra \\
\sum_{t \leq T} z_t^x \ps{\ell_t\of{p_t} - \ell_t\of{x}} &\leq \ra 
\end{align*}
\end{proof}

\subsection{Putting it all together}\label{alltogether}

In this section we update Algorithm~\ref{weakpea} to incorporate
the improvements described in the last two sections.
The result is Algorithm~\ref{strongpea}.

\newcommand{\epsV}{\epsilon_V}
\newcommand{\vs}{\mathcal{V}}
\newcommand{\diffsquared}{\ps{\ell_t\of{x} - \ell_t\of{p_t}}^2}
\begin{algorithm}\label{strongpea}
    \caption{Collaborative prediction with expert advice [full algorithm]}
    \Let{$\vs$}{$\b{1, 2, 4, \ldots, 2^{\floor{\log_2 T}}}$}
    \Let{$\epsV$}{$\min\b{1, \sqrt{\ps{\log{M} + \log\log{T}}/V}}$}
    \Let{$A_1$}{$\init{\experts \times \vs, \epsilon\of{x, V} = \epsV}$}
    \For{$x \in \experts, V \in \vs $}{
        \Let{$B^{x,V}_1$}{$\inits{\users}$}
    }
    \For{$t = 1, 2, \ldots$}{
        Observe $u_t \in \users$\;
        \For{$x \in \experts, V \in \vs$}{
            \Let{$z_t^{x, V}$}{$B^{x, V}_t\of{u_t}$}
            \Let{$w_t^{x, V}$}{$z_b^x \atx$}
        }
        \Let{$W_t$}{$\sum_{x, V} w_t^{x, V}$}
        Play $p_t\of{x} = \sum_V w_t^{x, V} / W_t \in \Delta\of{\experts}$\;
        Observe $\ell_t : \experts \rightarrow [-1, 1]$\;
        \For{$x \in \experts, V \in \vs$}{
            \Let{$\ell_t^A\of{x, V}$}{$z_t^{x, V} \ell_t\of{x} + \ps{1 - z_t^{x, V}} \ell_t\of{p_t}$}
            \Let{$\ell_t^{B^{x, V}}$}{$\ell_t\of{x} - \ell_t\of{p_t} + \epsV \diffsquared$}
            \Let{$B^{x, V}_{t+1}$}{$\updates{B^{x, V}_t}{u_t}{\ell_t^{B^{x, V}}}$}
        }
        \Let{$A_{t+1}$}{$\update{A_t}{\ell_t^A}$}
    }
\end{algorithm}
\begin{lemma}\label{reverselemmaplus}
For every $x \in \experts, V \in \vs, H \subset \users$:
\begin{align*}
\sum_{t \leq T} z_t^{x, V}
\ps{\ell_t\of{x} - \ell_t\of{p_t} + \epsV \diffsquared}
\leq & \sum_{t \leq T : u_t \in H} \ps{\ell_t\of{x} - \ell_t\of{p_t}}
+ \O{V_H \epsV }\\
&+\theregret
\end{align*}
where $V_H = \sum_{t \leq t : u_t \in H} \ps{\ell_t\of{x} - \ell_t\of{p_t}}^2$ and $\alpha = \abs{H} / N$.
\end{lemma}
\begin{proof}
We apply Lemma~\ref{mwms} directly to the instance $B^{x, V}$.
Note that $V_H \epsV$
is precisely the total loss caused by the penalty term $\epsV \ps{\ell_t\of{x} - \ell_t\of{p_t}}^2$
in all rounds $t$ with $u_t \in H$.

After adding this quadratic penalty term the payoffs $\ell_t^{B^{x, V}}$
are no longer in $[-1, 1]$, but they are still $\O{1}$.
This does not affect the asymptotics in the regret bound.
\end{proof}

