\end{proof}

\newcommand{\zt}{z_t^{x, V}}
\begin{lemma}\label{specialistlemmaplus}
For any $x \in \experts, V \in \vs$,
\[\sum_{t \leq T} \zt\ps{\ell_t\of{p_t} - \ell_t\of{x}}
\leq \epsV \sum_{t \leq T} \zt \diffsquared + \O{\frac{\log{M} + \log\log{T}}{\epsV}}\]
\end{lemma}
\begin{proof}
As before, we observe that $\ell^A_t\of{A_t} = \ell_t\of{p_t}$:
\renewcommand{\atx}{A_t\of{x, V}}
\begin{align*}
\ell^A_t\of{A_t} 
&= \sum_{x, V} \atx \ps{\zt \ell_t\of{x} + (1 - \zt) \ell_t\of{p_t}} \\
&= \sum_{x, V} \atx \zt \ell_t\of{x} + \ell_t\of{p_t} \sum_{x, V} \atx - \ell_t\of{p_t} \sum_{x, V} \atx \zt \\
&= \sum_{x, V} w_t^{x, V} \ell_t\of{x}  + \ell_t\of{p_t} - \ell_t\of{p_t} \sum_{x, V} w_t^{x, V} \\
&= W_t \ell_t\of{p_t} + \ell_t\of{p_t} - W_t \ell_t\of{p_t} \\
&= \ell_t\of{p_t}.
\end{align*} 
So we can apply the regret bound for $A$, and obtain:
\newcommand{\zdiff}{\zt \ell_t\of{x} + \ps{1 - \zt} \ell_t\of{p_t}}
\begin{align*}
\sum_{t \leq T} \ell_t\of{p_t}
=& \sum_{t \leq T} \ell^A_t\of{A_t} \\
\leq & \sum_{t \leq T} \ell^A_t\of{x, V} + \epsV \sum_{t \leq T} \ps{\ell^A_t\of{x, V} - \ell^A_t\of{p_t}}^2 + \O{\frac{\log{M} + \log\log{T}}{\epsV}}\\
=& \sum_{t \leq T} \ps{\zdiff}  \\
&+ \epsV \sum_{t \leq T} \ps{\zdiff - \ell_t\of{p_t}}^2  \\
&+ \O{\frac{\log{M} + \log\log{T}}{\epsV}}\\
=& \sum_{t \leq T} \ell_t\of{p_t} + \sum_{t \leq T} \zt \ps{\ell_t\of{x} - \ell_t\of{z_t}}
+ \epsV \sum_{t \leq T} \ps{\zt \ps{\ell_t\of{x} - \ell_t\of{p_t}}}^2 \\
&+ \O{\frac{\log{M} + \log\log{T}}{\epsV}}\\
\leq& \sum_{t \leq T} \ell_t\of{p_t} + \sum_{t \leq T} \zt \ps{\ell_t\of{x} - \ell_t\of{z_t}}
+ \epsV \sum_{t \leq T} \zt \ps{\ell_t\of{x} - \ell_t\of{p_t}}^2 \\
&+ \O{\frac{\log{M} + \log\log{T}}{\epsV}}\\
\sum_{t \leq T} \zt \ps{\ell_t\of{p_t} - \ell_t\of{x}} &\leq \epsV \sum_{t \leq T} \zt \diffsquared + \O{\frac{\log{M} + \log\log{T}}{\epsV}},
\end{align*}
as desired.
\end{proof}

\begin{theorem}\label{fullstatement}
For each $x$ and $H$,
algorithm~\ref{strongpea} satisfies
\[ \sum_{t \leq T: u_t \in H }{\ell_t\of{p_t}}
\leq \sum_{t \leq T : u_t \in H} {\ell_t\of{x}}
+ \Ot{\sqrt{V_H \log{M} + N\of{V_H \alpha \log{\frac 1{\alpha}} + V_{\users \backslash H} (1 - \alpha) \log{\frac 1{1 - \alpha}}}}}\]
Where $V_H = \sum_{t \leq T : u_t \in H}{\diffsquared}$ and $\alpha = \abs{H}/N$.
\end{theorem}
\begin{proof}
Note that $V_H \leq T$.
Thus there exists some $V \in \vs$ with $V \leq V_H \leq 2V$.

Applying Lemma~\ref{reverselemmaplus} with the pair $x, V$ we have:
\begin{align*}
\sum_{t \leq T : u_t \in H} \ps{\ell_t\of{p_t} - \ell_t\of{x}}
&\leq
\sum_{t \leq T} z_t^{x, V}
\ps{\ell_t\of{p_t} - \ell_t\of{x} - \epsV \diffsquared}
+ \O{\sqrt{V_H \logo{M}}}\\
&+\theregret
\end{align*}
Applying Lemma~\ref{specialistlemmaplus}:
\begin{align*}
\sum_{t \leq T} z_t^{x, V}
\ps{\ell_t\of{p_t} - \ell_t\of{x} - \epsV \diffsquared}
&\leq \O{\frac{\log{M} + \log\log{T}}{\epsV}}
&\leq \Ot{\sqrt{V_H \log{M}}}
\end{align*}
Combining the two inequalities gives the desired result.
\end{proof}
Corollary~\ref{simplestatement} follows immediately
from the observation that $V_H \leq T_H$,
and the inequality $\alpha^2 \log{\frac 1{\alpha}} + \of{1 - \alpha}^2 \log{\frac 1{1 - \alpha}} \leq 2 \alpha H_b\of{\alpha}$.

