\section{Defining $\mwms$}\label{mwmsappendix}


\newcommand{\ns}{\mathcal{N}}
\renewcommand{\epsV}[2]{\epsilon_{N_{#1}, V_{#1}}}
\newcommand{\indices}{N_D, N_H, V_D, V_H}
\newcommand{\loopindices}{N_D, N_H \in \ns, V_D, V_H \in \vs}
\begin{algorithm}\label{mwms}
    \caption{$\mwms$}
    \Let{$\vs$}{$\b{1, 2, 4, \ldots, 2^{\floor{\log_2 T}}}$}
    \Let{$\ns$}{$\b{1, 2, 4, \ldots, 2^{\floor{\log_2 N}}}$}
    \Let{$\Theta$}{$\ns^2 \times \vs^2$}
    \Let{$\epsV{S}{S}$}{$\sqrt{\ps{N_S \log \frac {N}{N_S} + \log\log T}/V_S}$}
    \Let{$A_1$}{$\init{\Theta, \epsilon = \sqrt{\ps{\log\log T + \log\log N} / T}}$}
    \For{$\loopindices, u \in \users$}{
        \Let{$B_1^{\indices, u}$}{$\init{\b{0, 1}, w(0) \propto N_D, w(1) \propto N_H, \epsilon(0) = \epsV{D}{D}, \epsilon(1) = \epsV{H}{H}}$}
        %YYY fix weird space
    }
    \For{$t = 1, 2, \ldots$}{
        Observe $u_t \in \users$\;
        Play $p_t = \sum_{\theta \in \Theta} A_t\of{\theta} B_t^{\theta, u_t}\of{1}$\;
        Observe $\ell_t \in [-1, 1]$\;
        \For{$\theta \in \Theta$}{
            \Let{$\ell_t^A\of{\theta}$}{$\ell_t B_t^{\theta, u_t}(1)$}
            \Let{$B_{t+1}^{\theta, u_t}$}{$\update{B_t^{\theta, u_t}}{\ell_t}$}
        }
        \Let{$A_{t+1}$}{$\update{A_t}{\ell_T^A}$}
    }
\end{algorithm}

Coping with the case $H = \users$ or $H = \emptyset$ actually requires a very slight adjustment to our algorithm:
we include in $\Theta$ a new pair of values $\theta = (0, 0, N, 0), (0, 0, 0, N)$,
and have $A_1$ assign these values an initial weight of $1/3$ and learning rate of $T^{-1/2}$.
This does not affect the asymptotics of our regret bound,
but ensures that we have regret $\Ot{0}$ whenever $H = \users$ or $H = \emptyset$.
\end{proof}


